package com.example.dealership.document;
import java.time.*; import java.util.*;
import com.example.dealership.error.NotFoundException;
import com.example.dealership.vehicle.*;
import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
@Service @Transactional(readOnly = true)
public class HandoverReadinessService {
    private final VehicleRepository vr; private final VehicleDocumentRepository dr; private final Clock clock;
    public HandoverReadinessService(VehicleRepository vr, VehicleDocumentRepository dr, Clock clock) { this.vr = vr; this.dr = dr; this.clock = clock; }
    public HandoverReadinessResponse check(Long id) {
        Vehicle v = vr.findById(id).orElseThrow(() -> new NotFoundException("Vehicle with id " + id + " not found"));
        List<VehicleDocument> docs = dr.findByVehicleId(id, Sort.by("id"));
        LocalDate ref = v.getPlannedHandoverDate() != null ? v.getPlannedHandoverDate() : LocalDate.now(clock);
        List<DocumentType> required = new ArrayList<>(List.of(DocumentType.SALES_AGREEMENT, DocumentType.INVOICE, DocumentType.COC, DocumentType.OC_POLICY));
        if (v.isRegistrationByDealer()) required.add(DocumentType.REGISTRATION_POA);
        List<DocumentType> missing = new ArrayList<>(); List<ReadinessProblem> problems = new ArrayList<>();
        for (DocumentType t : required) {
            Optional<VehicleDocument> d = docs.stream().filter(x -> x.getType() == t && x.getStatus() != DocumentStatus.REJECTED).findFirst();
            if (d.isEmpty()) { missing.add(t); continue; }
            if (d.get().getStatus() == DocumentStatus.PENDING) problems.add(new ReadinessProblem(t, ReadinessReason.NOT_VERIFIED));
            if (d.get().getExpiryDate() != null && d.get().getExpiryDate().isBefore(ref)) problems.add(new ReadinessProblem(t, ReadinessReason.EXPIRED));
        }
        if (v.getPlannedHandoverDate() == null) problems.add(new ReadinessProblem(null, ReadinessReason.NO_HANDOVER_DATE));
        return new HandoverReadinessResponse(missing.isEmpty() && problems.isEmpty(), missing, problems);
    }
}
