import jakarta.validation.ConstraintValidator; import jakarta.validation.ConstraintValidatorContext;
public class ExpiryNotBeforeIssueValidator implements ConstraintValidator<ExpiryNotBeforeIssue, DocumentRequest> {
    public boolean isValid(DocumentRequest r, ConstraintValidatorContext c) {
        if (r == null || r.issueDate() == null || r.expiryDate() == null || !r.expiryDate().isBefore(r.issueDate())) return true;
        c.disableDefaultConstraintViolation();
        c.buildConstraintViolationWithTemplate(c.getDefaultConstraintMessageTemplate()).addPropertyNode("expiryDate").addConstraintViolation();
        return false;
    }
}
