import { Component, inject, input, signal } from '@angular/core';
import { RouterLink } from '@angular/router';
import { problemDetailMessage } from '../shared/problem-detail';
import { DOCUMENT_STATUS_LABELS, DOCUMENT_TYPE_LABELS, VehicleDocumentApi, VehicleDocumentStatus } from './vehicle-document-api';
import { VehicleHandoverReadiness } from './vehicle-handover-readiness';

@Component({ selector: 'app-vehicle-documents-section', imports: [RouterLink, VehicleHandoverReadiness], templateUrl: './vehicle-documents-section.html' })
export class VehicleDocumentsSection {
  private readonly api = inject(VehicleDocumentApi);
  readonly vehicleId = input.required<number>();
  protected readonly documents = this.api.list(this.vehicleId);
  protected readonly readiness = this.api.readiness(this.vehicleId);
  protected readonly registration = this.api.registration(this.vehicleId);
  protected readonly typeLabels = DOCUMENT_TYPE_LABELS;
  protected readonly statusLabels = DOCUMENT_STATUS_LABELS;
  protected readonly error = signal<string | null>(null);

  protected change(id: number, status: VehicleDocumentStatus) {
    this.error.set(null);
    this.api.changeStatus(this.vehicleId(), id, status).subscribe({
      next: () => { this.documents.reload(); this.readiness.reload(); },
      error: (e) => this.error.set(problemDetailMessage(e)),
    });
  }
  protected toggle(event: Event) {
    const checked = (event.target as HTMLInputElement).checked;
    this.api.setRegistrationByDealer(this.vehicleId(), checked).subscribe({
      next: () => { this.registration.reload(); this.readiness.reload(); },
      error: (e) => this.error.set(problemDetailMessage(e)),
    });
  }
}
EOF
